-- =============================================================================
-- Ranking Unoeste — ajustes no Supabase
-- Rode este arquivo inteiro no SQL Editor do Supabase (Run).
-- É seguro rodar mais de uma vez: nada é apagado e nada que já existe é
-- sobrescrito (só cria o que falta).
-- =============================================================================

-- 1) Tabela de fotos --------------------------------------------------------
-- Já existe no seu projeto (com a foto da Laura). Este bloco só garante a
-- estrutura caso você recrie o projeto do zero.
create table if not exists public.fotos (
  nome text not null,
  foto text not null            -- data URI (data:image/webp;base64,...) ou URL
);

alter table public.fotos add column if not exists atualizado_em timestamptz default now();

-- "nome" precisa ser único para o upload do admin fazer upsert (on_conflict=nome).
-- Se este comando falhar, existem nomes repetidos em "fotos": apague a cópia
-- duplicada manualmente e rode de novo.
create unique index if not exists fotos_nome_key on public.fotos (nome);

-- 2) Permissões da tabela fotos ---------------------------------------------
-- Mesmo modelo de acesso que o admin já usa hoje na tabela "ranking":
-- a chave pública (anon) pode ler e gravar. Veja no README a proposta de senha.
alter table public.fotos enable row level security;

drop policy if exists "fotos leitura publica" on public.fotos;
create policy "fotos leitura publica" on public.fotos
  for select to anon, authenticated using (true);

drop policy if exists "fotos insert anon" on public.fotos;
create policy "fotos insert anon" on public.fotos
  for insert to anon, authenticated with check (true);

drop policy if exists "fotos update anon" on public.fotos;
create policy "fotos update anon" on public.fotos
  for update to anon, authenticated using (true) with check (true);

grant select, insert, update on public.fotos to anon, authenticated;

-- 3) Laura Miranda no ranking Presencial --------------------------------------
-- Em 27/11 ela JÁ estava na tabela (id 14, valor 3). Este insert só roda se
-- ela não existir, com o valor de 22/11 (1 matrícula). Não altera o valor atual.
insert into public.ranking (nome, valor, tipo, ordem, ativo)
select 'Laura Miranda', 1, 'presencial',
       coalesce((select max(ordem) from public.ranking where tipo = 'presencial'), 0) + 1,
       true
where not exists (
  select 1 from public.ranking where nome = 'Laura Miranda' and tipo = 'presencial'
);

-- Garante que ela aparece na TV (se existir e estiver desativada)
update public.ranking set ativo = true
where nome = 'Laura Miranda' and tipo = 'presencial' and ativo is distinct from true;

